From 94715556fc5e1ee5b810b805e76f34002962e433 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 17:45:45 +0100
Subject: [PATCH] wizard: allow pairing again devices that are already paired

The wizard hid every paired device, so a controller paired to another
computer had to be removed in the settings first. Paired devices found
by the scan are now listed, and picking one removes and re-pairs it.

BUG: 503988
---
 src/wizard/pages/discover.cpp | 18 ++++++------
 src/wizard/pages/pairing.cpp  | 52 +++++++++++++++++++++++++++++++++++
 src/wizard/pages/pairing.h    |  3 ++
 3 files changed, 65 insertions(+), 8 deletions(-)

diff --git a/src/wizard/pages/discover.cpp b/src/wizard/pages/discover.cpp
index 8f3786e7..74c0bd8e 100644
--- a/src/wizard/pages/discover.cpp
+++ b/src/wizard/pages/discover.cpp
@@ -10,6 +10,8 @@
 #include "../wizardagent.h"
 #include "bluedevil_wizard.h"

+#include <limits>
+
 #include <QAction>
 #include <QRegularExpressionValidator>
 #include <QScroller>
@@ -100,8 +102,11 @@ bool DevicesProxyModel::filterAcceptsRow(int sourceRow, const QModelIndex &sourc
 {
     QModelIndex index = sourceModel()->index(sourceRow, 0, sourceParent);

-    bool devicePaired = index.data(BluezQt::DevicesModel::PairedRole).toBool();
-    if (devicePaired) {
+    // Paired devices are only offered for pairing again when they were found by the current scan
+    const bool devicePaired = index.data(BluezQt::DevicesModel::PairedRole).toBool();
+    const bool deviceConnected = index.data(BluezQt::DevicesModel::ConnectedRole).toBool();
+    const bool deviceDiscovered = index.data(BluezQt::DevicesModel::RssiRole).toInt() != std::numeric_limits<qint16>::min();
+    if (devicePaired && (deviceConnected || !deviceDiscovered)) {
         return false;
     }

@@ -237,7 +242,7 @@ void DiscoverPage::initializePage()

 bool DiscoverPage::isComplete() const
 {
-    if (!m_wizard->device() || m_wizard->device()->isPaired()) {
+    if (!m_wizard->device()) {
         return false;
     }

@@ -264,11 +269,8 @@ int DiscoverPage::nextId() const

     BluezQt::DevicePtr device = m_wizard->device();

-    if (device->isPaired()) {
-        return BlueWizard::Discover;
-    }
-
-    if (m_adapter && m_adapter->isDiscovering()) {
+    // A paired device is removed and found again by the pairing page, which needs discovery
+    if (m_adapter && m_adapter->isDiscovering() && !device->isPaired()) {
         qCDebug(BLUEDEVIL_WIZARD_LOG) << "Stopping scanning";
         m_adapter->stopDiscovery();
     }
diff --git a/src/wizard/pages/pairing.cpp b/src/wizard/pages/pairing.cpp
index 81aa14f7..47b741bc 100644
--- a/src/wizard/pages/pairing.cpp
+++ b/src/wizard/pages/pairing.cpp
@@ -17,6 +17,7 @@
 #include <KStandardGuiItem>

 #include <BluezQt/Adapter>
+#include <BluezQt/Device>
 #include <BluezQt/PendingCall>

 PairingPage::PairingPage(BlueWizard *parent)
@@ -62,10 +63,54 @@ void PairingPage::initializePage()
     connect(m_wizard->agent(), &WizardAgent::pinRequested, this, &PairingPage::pinRequested);
     connect(m_wizard->agent(), &WizardAgent::confirmationRequested, this, &PairingPage::confirmationRequested);

+    if (m_device->isPaired()) {
+        removeAndPair();
+        return;
+    }
+
+    pair();
+}
+
+void PairingPage::pair()
+{
     BluezQt::PendingCall *pairCall = m_device->pair();
     connect(pairCall, &BluezQt::PendingCall::finished, this, &PairingPage::pairingFinished);
 }

+void PairingPage::removeAndPair()
+{
+    // BlueZ refuses to pair a device again, so forget the old pairing and wait for the scan to find it again
+    const BluezQt::AdapterPtr adapter = m_device->adapter();
+    const QString address = m_device->address();
+
+    m_deviceAddedConnection = connect(adapter.data(), &BluezQt::Adapter::deviceAdded, this, [this, adapter, address](BluezQt::DevicePtr device) {
+        if (device->address() != address) {
+            return;
+        }
+        disconnect(m_deviceAddedConnection);
+
+        if (adapter->isDiscovering()) {
+            adapter->stopDiscovery();
+        }
+
+        m_device = device;
+        m_wizard->setDevice(device);
+        pair();
+    });
+
+    if (!adapter->isDiscovering()) {
+        adapter->startDiscovery();
+    }
+
+    BluezQt::PendingCall *removeCall = adapter->removeDevice(m_device);
+    connect(removeCall, &BluezQt::PendingCall::finished, this, [this](BluezQt::PendingCall *call) {
+        if (call->error()) {
+            disconnect(m_deviceAddedConnection);
+            pairingFinished(call);
+        }
+    });
+}
+
 void PairingPage::pairingFinished(BluezQt::PendingCall *call)
 {
     qCDebug(BLUEDEVIL_WIZARD_LOG) << "Pairing finished:";
@@ -143,6 +188,13 @@ void PairingPage::notMatchClicked()

 void PairingPage::cancelClicked()
 {
+    if (m_deviceAddedConnection) {
+        disconnect(m_deviceAddedConnection);
+        m_success = false;
+        m_wizard->next();
+        return;
+    }
+
     m_device->cancelPairing();
 }

diff --git a/src/wizard/pages/pairing.h b/src/wizard/pages/pairing.h
index 1f278bd5..d9992f1a 100644
--- a/src/wizard/pages/pairing.h
+++ b/src/wizard/pages/pairing.h
@@ -36,10 +36,13 @@ public Q_SLOTS:
     void cancelClicked();

 private:
+    void pair();
+    void removeAndPair();
     QList<QWizard::WizardButton> wizardButtonsLayout() const;

     BlueWizard *const m_wizard;
     BluezQt::DevicePtr m_device;
     BluezQt::Request<> m_req;
+    QMetaObject::Connection m_deviceAddedConnection;
     bool m_success = false;
 };
